# Sample from mid-range files to see progression
python3 << 'EOF'
import json
import os
from datetime import datetime

# Sample files from different dates
test_files = {
    "2026-07-20": ["/Users/sashaabramovich/.claude/projects/-Users-sashaabramovich/969ebaf6-879f-4cdd-8fb8-c9922acecb4f.jsonl"],
    "2026-07-22": [],
    "2026-07-24": [],
    "2026-08-12": [],
    "2026-08-13": [],
}

# Find one file from each date
import glob
for f in glob.glob("/Users/sashaabramovich/.claude/projects/-Users-sashaabramovich/*.jsonl"):
    try:
        j = json.loads(open(f).readline())
        ts = j.get('timestamp', '')
        if ts:
            date = ts[:10]
            if date in test_files and not test_files[date]:
                test_files[date].append(f)
    except: pass

# Analyze
for date in sorted(test_files.keys()):
    if test_files[date]:
        fpath = test_files[date][0]
        fname = os.path.basename(fpath)
        print(f"\n{date} ({fname})")
        violations = []
        for line in open(fpath):
            try:
                j = json.loads(line.strip())
                if j.get('type') == 'assistant':
                    content = j.get('message', {}).get('content', [])
                    for block in content:
                        if 'text' in block:
                            text = block['text']
                            if '"law": ' in text:
                                import re
                                laws = re.findall(r'"law": (\d+)', text)
                                violations.extend(laws)
            except: pass
        if violations:
            from collections import Counter
            counts = Counter(violations)
            for law, count in sorted(counts.items()):
                print(f"  Law {law}: {count} violations")
        else:
            print("  (no judge violations found)")
EOF
